// Consumer test — defines the expected contract
await pact
  .given('user 123 exists')
  .uponReceiving('a request for user 123')
  .withRequest({
    method: 'GET',
    path: '/users/123',
    headers: { 'API-Version': '1' }
  })
  .willRespondWith({
    status: 200,
    headers: { 'Content-Type': 'application/json' },
    body: {
      id: like('123'),
      username: like('alice'),
      email: like('alice@example.com')
      // If provider removes 'username', this test fails
    }
  })
  .execute(async () => {
    await api.getUser('123');
  });
